mapper.select:
SELECT r.id, r.repair_no, r.device_id, d.code AS device_code, d.name AS device_name, r.fault_desc, r.reporter, r.report_time, r.status, r.repairer, r.fault_reason, r.finish_time, (SELECT COALESCE(SUM(i.cost_ref), 0) FROM eqp_repair_item i WHERE i.repair_id = r.id AND i.deleted = 0) AS spare_cost, r.remark, r.create_time FROM eqp_repair r LEFT JOIN eqp_device d ON d.id = r.device_id WHERE r.deleted = 0
AND r.status = #{q.status}
AND r.device_id = #{q.deviceId}
AND (r.repair_no LIKE CONCAT('%', #{q.keyword}, '%') OR d.code LIKE CONCAT('%', #{q.keyword}, '%') OR d.name LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY r.id DESC
